jobs.label:
cat > /tmp/capture-jobs.mjs <<'EOF'
#!/usr/bin/env node
// Read one session's job roster (job/list), read-only.
const origin = (process.argv[2] ?? 'http://127.0.0.1:3080').replace(/\/$/, '')
const sessionId = process.argv[3]
const wsUrl = origin.replace(/^http/, 'ws') + '/api/remote.mux'
const ws = new WebSocket(wsUrl)
const frames = []
await new Promise((res, rej) => {
  ws.addEventListener('open', res, { once: true })
  ws.addEventListener('error', (e) => rej(new Error(e.message ?? 'socket error')), { once: true })
})
ws.send(JSON.stringify({
  type: 'open', streamId: 'jl', endpoint: 'job/list',
  payload: { args: { request: { sessionId } } },
}))
ws.addEventListener('message', (event) => {
  let msg
  try { msg = JSON.parse(String(event.data)) } catch { return }
  if (msg.type !== 'item') return
  frames.push(msg.value)
})
await new Promise((r) => setTimeout(r, 4000))
console.log(JSON.stringify({ note: 'One session\'s `job/list` roster, read from a live 0.1.7 Host.', capturedAgainst: origin, sessionId, frames }, null, 1))
process.exit(0)
EOF
cd /tmp && timeout 60 node /tmp/capture-jobs.mjs http://127.0.0.1:3080 session-a8107455-26ab-4c3f-b77c-b811a814ad83 > /tmp/jobs-capture.json 2>/tmp/jobs-capture.err; echo "EXIT=$?"; head -c 1200 /tmp/jobs-capture.json; echo; cat /tmp/jobs-capture.err | head -3
